parameters.jsCode:
// Validate the incoming timetable request and build the email.
// Input: the Webhook item. The JSON body sent by the caller is in $json.body.
const body = $input.first().json.body || {};
const errors = [];

// ---------- recipient ----------
const EMAIL_RE = /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/;
let recipient = typeof body.recipient === 'string' ? body.recipient.trim() : '';
if (!recipient) {
  errors.push('"recipient" is required (an email address).');
} else {
  const addresses = recipient.split(',').map(a => a.trim()).filter(Boolean);
  const bad = addresses.filter(a => !EMAIL_RE.test(a));
  if (addresses.length === 0 || bad.length > 0) {
    errors.push(`"recipient" contains an invalid email address: ${bad.join(', ') || recipient}`);
  }
  recipient = addresses.join(', ');
}

// ---------- subject ----------
let subject = 'Your Course Timetable';
if (body.subject !== undefined && body.subject !== null) {
  if (typeof body.subject !== 'string') {
    errors.push('"subject" must be text if provided.');
  } else if (body.subject.trim()) {
    subject = body.subject.trim();
  }
}

// ---------- display helpers ----------
// The scheduler API sends short days ("Mon") and times with seconds ("09:00:00").
const DAY_NAMES = { mon: 'Monday', tue: 'Tuesday', wed: 'Wednesday', thu: 'Thursday', fri: 'Friday', sat: 'Saturday', sun: 'Sunday' };
const fullDay = d => DAY_NAMES[d.slice(0, 3).toLowerCase()] || d;

// ---------- schedule ----------
const schedule = body.schedule;
const REQUIRED = ['course', 'day', 'time', 'room'];
const entries = [];
if (!Array.isArray(schedule)) {
  errors.push('"schedule" is required and must be a list of timetable entries.');
} else if (schedule.length === 0) {
  errors.push('"schedule" is empty. There is no timetable to send.');
} else {
  schedule.forEach((entry, i) => {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      errors.push(`schedule[${i}] must be an object.`);
      return;
    }
    const missing = REQUIRED.filter(k => entry[k] === undefined || entry[k] === null || String(entry[k]).trim() === '');
    if (missing.length) {
      errors.push(`schedule[${i}] is missing: ${missing.join(', ')}.`);
      return;
    }
    entries.push({
      course: String(entry.course).trim(),
      title: entry.title ? String(entry.title).trim() : '',
      // "lecturer" is the scheduler's field name; "instructor" is the database term.
      lecturer: (entry.lecturer || entry.instructor)
        ? String(entry.lecturer || entry.instructor).trim()
        : '',
      day: fullDay(String(entry.day).trim()),
      time: String(entry.time).trim().replace(/(\b\d{1,2}:\d{2}):\d{2}\b/g, '$1'),
      room: String(entry.room).trim(),
    });
  });
}

if (errors.length) {
  return [{ json: { valid: false, errors } }];
}

// ---------- sort: day of week, then start time ----------
const DAY_ORDER = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const dayRank = d => {
  const i = DAY_ORDER.indexOf(d.slice(0, 3).toLowerCase());
  return i === -1 ? 99 : i;
};
entries.sort((a, b) =>
  dayRank(a.day) - dayRank(b.day) ||
  a.time.localeCompare(b.time) ||
  a.course.localeCompare(b.course)
);

// ---------- plain-text version (matches the task example) ----------
const label = e => (e.title ? `${e.course} - ${e.title}` : e.course);
const text = [subject, '']
  .concat(entries.map(e =>
    `${label(e)}\n${e.day} | ${e.time} | ${e.room}${e.lecturer ? ` | ${e.lecturer}` : ''}\n`))
  .join('\n');

// Show the Lecturer column only when at least one class has a lecturer.
const showLecturer = entries.some(e => e.lecturer);
const columnCount = showLecturer ? 5 : 4;

// ---------- HTML version (what Gmail sends) ----------
const esc = s => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const cell = 'padding:8px 10px;border-bottom:1px solid #e3e8ef;';
let rows = '';
let lastDay = null;
for (const e of entries) {
  if (e.day !== lastDay) {
    rows += `<tr><td colspan="${columnCount}" style="padding:10px 10px 6px;background:#eef3f8;font-weight:bold;color:#16324f;">${esc(e.day)}</td></tr>`;
    lastDay = e.day;
  }
  rows += `<tr>`
    + `<td style="${cell}white-space:nowrap;">${esc(e.time)}</td>`
    + `<td style="${cell}font-weight:bold;white-space:nowrap;">${esc(e.course)}</td>`
    + `<td style="${cell}">${esc(e.title)}</td>`
    + (showLecturer ? `<td style="${cell}">${esc(e.lecturer)}</td>` : '')
    + `<td style="${cell}white-space:nowrap;">${esc(e.room)}</td>`
    + `</tr>`;
}

const plural = entries.length === 1 ? 'class' : 'classes';
const html = `<div style="font-family:Arial,Helvetica,sans-serif;color:#1c2430;max-width:640px;">
<h2 style="color:#0f2a44;margin:0 0 6px;">${esc(subject)}</h2>
<p style="margin:0 0 14px;color:#4a5667;">${entries.length} ${plural}, listed by day and time.</p>
<table style="border-collapse:collapse;width:100%;font-size:14px;">
<thead><tr>
<th style="text-align:left;padding:8px 10px;background:#16324f;color:#ffffff;">Time</th>
<th style="text-align:left;padding:8px 10px;background:#16324f;color:#ffffff;">Course</th>
<th style="text-align:left;padding:8px 10px;background:#16324f;color:#ffffff;">Title</th>
${showLecturer ? '<th style="text-align:left;padding:8px 10px;background:#16324f;color:#ffffff;">Lecturer</th>' : ''}
<th style="text-align:left;padding:8px 10px;background:#16324f;color:#ffffff;">Room</th>
</tr></thead>
<tbody>${rows}</tbody>
</table>
<p style="margin:16px 0 0;font-size:12px;color:#7a8696;">Generated by the Group 4 Auto-Scheduler.</p>
</div>`;

return [{ json: { valid: true, recipient, subject, entries_count: entries.length, text, html } }];

